import {
	LayoutChangeEvent,
	NativeScrollEvent,
	NativeSyntheticEvent,
	View
} from 'react-native'
import { Item } from './utils/types'
import { ChatBlock } from './components/ChatBlock'
import { defineStyles } from '@/utils/defineStyles'
import { FlashList, FlashListRef } from '@shopify/flash-list'
import { useEffect, useRef, useState } from 'react'
import { useChatStore } from './store/chatStore'
import { NEW_THREAD, useThreadId } from './store/threadStore'
import { MESSAGE_BOTTOM_CONTAINER_GAP } from '@/constants'
import { closeChatEmitter, CloseChatEvents } from '@/utils/emitter'

export const ChatStreamContainer = ({
	messages,
	bottomContainerHeight,
	isLauncher
}: {
	messages: Item[]
	bottomContainerHeight: number
	isLauncher: boolean
}) => {
	const flashListRef = useRef<FlashListRef<Item>>(null)
	const [chatHeight, setChatHeight] = useState(0)
	const scrollYAtDragStart = useRef<number | null>(null)

	const threadId = useThreadId()
	const isGenerating = useChatStore((state) =>
		threadId === NEW_THREAD
			? false
			: state.value.isGenerating.get(threadId) ?? false
	)

	const handleScrollBeginDrag = (
		event: NativeSyntheticEvent<NativeScrollEvent>
	) => {
		if (isLauncher) {
			return
		}
		const scrollY = event.nativeEvent.contentOffset.y
		scrollYAtDragStart.current = scrollY
	}

	const handleScroll = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
		if (isLauncher) {
			return
		}
		const scrollY = event.nativeEvent.contentOffset.y
		if (scrollY > 0) {
			scrollYAtDragStart.current = null
		}
		if (
			scrollYAtDragStart.current !== null &&
			scrollY < scrollYAtDragStart.current
		) {
			closeChatEmitter.emit(CloseChatEvents.CLOSE_CHAT)
		}
	}

	const handleLayout = (event: LayoutChangeEvent) => {
		const { height } = event.nativeEvent.layout
		setChatHeight(height)
	}

	useEffect(() => {
		flashListRef.current?.scrollToEnd({ animated: true })
	}, [messages.length])

	return (
		<FlashList
			ref={flashListRef}
			data={messages}
			showsVerticalScrollIndicator={false}
			showsHorizontalScrollIndicator={false}
			onScroll={handleScroll}
			onScrollBeginDrag={handleScrollBeginDrag}
			scrollEventThrottle={16}
			renderItem={({ item, index }) => {
				if (item.type === 'message') {
					if (
						index === 0 &&
						item.data.actor === 'assistant' &&
						item.data.blocks.length === 0
					) {
						return <></>
					}
					const lastUserIndex = [...messages]
						.reverse()
						.findIndex(
							(msg) => msg.type === 'message' && msg.data?.actor === 'user'
						)
					const lastUserMessage =
						lastUserIndex !== -1
							? messages[messages.length - 1 - lastUserIndex]
							: null
					const isLastUserMessage =
						lastUserMessage &&
						lastUserMessage.type === 'message' &&
						lastUserMessage.data === item.data

					return (
						<ChatBlock
							message={item.data}
							chatHeight={chatHeight}
							isLastUserMessage={!!isLastUserMessage}
							bottomContainerHeight={bottomContainerHeight}
							isLauncher={isLauncher}
						/>
					)
				}
				return <></>
			}}
			style={styles.list}
			nestedScrollEnabled={true}
			scrollEnabled={true}
			ItemSeparatorComponent={() => <View style={{ height: 32 }} />}
			contentContainerStyle={[
				styles.listContainer,
				{
					paddingBottom:
						bottomContainerHeight + MESSAGE_BOTTOM_CONTAINER_GAP + 24
				}
			]}
			keyExtractor={(_, index) => index.toString()}
			onContentSizeChange={() => {
				flashListRef.current?.scrollToEnd({ animated: true })
			}}
			onLayout={(event) => {
				if (isGenerating) {
					flashListRef.current?.scrollToEnd({ animated: true })
				}
				if (chatHeight === 0) {
					handleLayout(event)
				}
			}}
		/>
	)
}

const styles = defineStyles({
	list: { flex: 1, backgroundColor: 'transparent' },
	listContainer: {
		flexGrow: 1,
		paddingHorizontal: 20,
		paddingTop: 20,
		justifyContent: 'flex-end'
	}
})
